use strict; use warnings; use JSON::PP;
my @rows;
for my $path (@ARGV) {
    open my $fh, '<:raw', $path or die "open whole index width: $!";
    my ($bytes, $lines, $width) = (0, 0, 0);
    while (my $row = <$fh>) {
        $bytes += length($row);
        $lines += ($row =~ s/\n\z//);
        $row =~ s/\r\z//;
        $width = length($row) if length($row) > $width;
    }
    close $fh or die "close whole index width: $!";
    push @rows, {bytes => $bytes, lines => $lines, max_line_bytes => $width};
}
print JSON::PP->new->canonical->encode(\@rows), "\n";

